DO $test$
DECLARE a uuid:='10000000-0000-4000-8000-000000000001'; b uuid:='10000000-0000-4000-8000-000000000002';
 i uuid:='20000000-0000-4000-8000-000000000001'; o uuid:='30000000-0000-4000-8000-000000000001'; result jsonb; blocked boolean;
BEGIN
 INSERT INTO airlinerra_game.airlines VALUES(a,1,500000),(b,1,500000);
 INSERT INTO airlinerra_game.airline_ledger(airline_id,entry_kind,amount_usd) VALUES(a,'STARTING_CAPITAL',500000),(b,'STARTING_CAPITAL',500000);
 INSERT INTO airlinerra_game.airline_aircraft_inventory VALUES(i,a,'stored','leased','YU-ALB',106);
 INSERT INTO airlinerra_game.aircraft_acquisition_orders_v1 VALUES(o,1,a,i,'lease','YU-ALB',106,'awaiting_delivery','2027-01-31 08:00+00',2,133000);
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,1);
 IF result->>'status'<>'delivery_not_verified' THEN RAISE EXCEPTION 'Unverified delivery accepted %',result;END IF;
 UPDATE airlinerra_game.airline_aircraft_inventory SET fleet_status='in_service' WHERE id=i;
 UPDATE airlinerra_game.aircraft_acquisition_orders_v1 SET order_status='delivered_pending_inspection' WHERE order_id=o;
 INSERT INTO airlinerra_game.section9_aircraft_delivery_position_v1 VALUES(o,i,a,1,'2027-01-31','2027-01-31 09:00+00','2027-01-31 09:00+00');
 blocked:=false;
 BEGIN PERFORM airlinerra_game.post_aircraft_lease_month_v1(b,o,1); EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Foreign airline payment accepted';END IF;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,2);
 IF result->>'status'<>'requires_next_month' THEN RAISE EXCEPTION 'Skipped first month';END IF;
 result:=airlinerra_game.aircraft_lease_departure_coverage_v1(a,i,'2027-01-31 13:00+00','2027-01-31 15:00+00');
 IF result->>'status'<>'lease_payment_due' OR (result->>'eligible')::boolean THEN RAISE EXCEPTION 'Unpaid lease eligible %',result;END IF;
 result:=airlinerra_game.run_aircraft_lease_billing_v1(10);
 IF jsonb_array_length(result->'results')<>1 OR result->'results'->0->>'status'<>'paid' OR result->'results'->0->>'coverageEndGameDate'<>'2027-02-28' THEN RAISE EXCEPTION 'Wrong first batch receipt %',result;END IF;
 result:=airlinerra_game.run_aircraft_lease_billing_v1(10);
 IF jsonb_array_length(result->'results')<>0 THEN RAISE EXCEPTION 'Batch charged twice %',result;END IF;
 result:=airlinerra_game.aircraft_lease_departure_coverage_v1(a,i,'2027-01-31 13:00+00','2027-01-31 15:00+00');
 IF result->>'status'<>'lease_paid_coverage' OR (result->>'eligible')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'Paid flight blocked %',result;END IF;
 result:=airlinerra_game.aircraft_lease_departure_coverage_v1(a,i,'2027-02-27 22:00+00','2027-02-28 00:00+00');
 IF result->>'status'<>'lease_payment_due' OR (result->>'eligible')::boolean THEN RAISE EXCEPTION 'Flight exceeds paid coverage %',result;END IF;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,1);
 IF result->>'status'<>'already_paid' OR (SELECT cash_usd FROM airlinerra_game.airlines WHERE id=a)<>367000 THEN RAISE EXCEPTION 'Duplicate debit';END IF;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,2);
 IF result->>'status'<>'not_due' THEN RAISE EXCEPTION 'Charged before due date';END IF;
 UPDATE airlinerra_game.test_clock SET t='2027-02-28 12:00+00';
 UPDATE airlinerra_game.airlines SET cash_usd=100 WHERE id=a;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,2);
 IF result->>'status'<>'cash_ledger_unreconciled' THEN RAISE EXCEPTION 'Cash mismatch accepted';END IF;
 INSERT INTO airlinerra_game.airline_ledger(airline_id,entry_kind,amount_usd) VALUES(a,'EXPENSE',-366900);
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,2);
 IF result->>'status'<>'insufficient_cash' OR (SELECT count(*) FROM airlinerra_game.aircraft_lease_monthly_receipts_v1)<>1 THEN RAISE EXCEPTION 'Unfunded payment accepted';END IF;
 INSERT INTO airlinerra_game.airline_ledger(airline_id,entry_kind,amount_usd) VALUES(a,'REVENUE',200000);
 UPDATE airlinerra_game.airlines SET cash_usd=cash_usd+200000 WHERE id=a;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,2);
 IF result->>'status'<>'paid' OR result->>'coverageEndGameDate'<>'2027-03-31' THEN RAISE EXCEPTION 'Wrong second receipt %',result;END IF;
 result:=airlinerra_game.post_aircraft_lease_month_v1(a,o,3);
 IF result->>'status'<>'contract_term_complete' THEN RAISE EXCEPTION 'Extra month charged';END IF;
 result:=airlinerra_game.aircraft_lease_departure_coverage_v1(a,i,'2027-03-30 22:00+00','2027-03-31 01:00+00');
 IF result->>'status'<>'lease_term_expired' OR (result->>'eligible')::boolean THEN RAISE EXCEPTION 'Expired contract allowed flight %',result;END IF;
 result:=airlinerra_game.run_aircraft_lease_billing_v1(10);
 IF jsonb_array_length(result->'results')<>0 THEN RAISE EXCEPTION 'Completed contract billed again %',result;END IF;
 IF (SELECT cash_usd FROM airlinerra_game.airlines WHERE id=a)<>67100 OR (SELECT sum(amount_usd) FROM airlinerra_game.airline_ledger WHERE airline_id=a)<>67100 OR (SELECT count(*) FROM airlinerra_game.airline_ledger WHERE airline_id=a AND entry_kind='AIRCRAFT_LEASE')<>2 OR (SELECT cash_usd FROM airlinerra_game.airlines WHERE id=b)<>500000 THEN RAISE EXCEPTION 'Final reconciliation failed';END IF;
 blocked:=false;
 BEGIN DELETE FROM airlinerra_game.aircraft_lease_monthly_receipts_v1 WHERE order_id=o; EXCEPTION WHEN SQLSTATE '42501' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Receipt history not immutable';END IF;
 IF has_function_privilege('authenticated','airlinerra_game.post_aircraft_lease_month_v1(uuid,uuid,integer)','EXECUTE') OR has_function_privilege('anon','airlinerra_game.post_aircraft_lease_month_v1(uuid,uuid,integer)','EXECUTE') OR has_function_privilege('service_role','airlinerra_game.post_aircraft_lease_month_v1(uuid,uuid,integer)','EXECUTE') THEN RAISE EXCEPTION 'Private payment function exposed';END IF;
 RAISE NOTICE 'PASS verified delivery, owner isolation, chronological months, month-end dates, replay, future due date, cash mismatch, insufficient funds, expiry billing cap, balance/ledger reconciliation and private immutable receipts';
END $test$;
